package com.blockcrush.puzzle.audio

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import com.blockcrush.puzzle.Prefs
import com.blockcrush.puzzle.R

/** Plays the short sound effects. All sounds are original and generated by tools/gen_sounds.py. */
class SoundManager(context: Context, private val prefs: Prefs) {

    enum class Sfx(val resId: Int) {
        PICKUP(R.raw.sfx_pickup),
        PLACE(R.raw.sfx_place),
        INVALID(R.raw.sfx_invalid),
        CLEAR_1(R.raw.sfx_clear_1),
        CLEAR_2(R.raw.sfx_clear_2),
        CLEAR_3(R.raw.sfx_clear_3),
        COMBO(R.raw.sfx_combo),
        BOARD_CLEAR(R.raw.sfx_board_clear),
        GAME_OVER(R.raw.sfx_game_over),
        NEW_BEST(R.raw.sfx_new_best),
        BUTTON(R.raw.sfx_button),
        ACHIEVEMENT(R.raw.sfx_achievement),
        CHALLENGE(R.raw.sfx_challenge),
        CONTINUE(R.raw.sfx_continue)
    }

    private val pool: SoundPool = SoundPool.Builder()
        .setMaxStreams(8)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()

    private val sampleIds = IntArray(Sfx.values().size)
    private val loaded = BooleanArray(Sfx.values().size)

    init {
        pool.setOnLoadCompleteListener { _, sampleId, status ->
            if (status == 0) {
                val index = sampleIds.indexOf(sampleId)
                if (index >= 0) loaded[index] = true
            }
        }
        for (sfx in Sfx.values()) {
            sampleIds[sfx.ordinal] = pool.load(context, sfx.resId, 1)
        }
    }

    /** Plays a sound if sound effects are enabled. [rate] 0.5..2.0 changes pitch and speed. */
    fun play(sfx: Sfx, volume: Float = 1f, rate: Float = 1f) {
        if (!prefs.soundOn) return
        val index = sfx.ordinal
        if (!loaded[index]) return
        val v = volume.coerceIn(0f, 1f)
        pool.play(sampleIds[index], v, v, 1, 0, rate.coerceIn(0.5f, 2f))
    }

    /** Line clear sound scaled by how many lines went at once, plus a combo flourish. */
    fun playClear(lines: Int, combo: Int) {
        when {
            lines >= 3 -> play(Sfx.CLEAR_3)
            lines == 2 -> play(Sfx.CLEAR_2)
            else -> play(Sfx.CLEAR_1)
        }
        if (combo >= 2) {
            play(Sfx.COMBO, volume = 0.9f, rate = (1f + 0.06f * (combo - 2)).coerceAtMost(1.6f))
        }
    }

    fun release() {
        pool.release()
    }
}
